class Solution { public int minCost(int[] nums,int k){int n=nums.length;int[] dp=new int[n+1];Arrays.fill(dp,Integer.MAX_VALUE/2);dp[0]=0;for(int left=0;left<n;left++){int[] frequency=new int[n+1];int trimmed=0;for(int right=left;right<n;right++){int count=++frequency[nums[right]];if(count==2)trimmed+=2;else if(count>2)trimmed++;dp[right+1]=Math.min(dp[right+1],dp[left]+k+trimmed);}}return dp[n];} }
